  +    fn flush(&mut self) -> std::io::Result<()> {
  +        if !self.buf.is_empty() {
  +            let out = rewrite_sgr(&self.buf);
  +            self.buf.clear();
  +            self.inner.write_all(&out)?;
  +        }
